    let ref_png = out_dir.join(format!("{}.ref.png", tc.id));
    let cand_png = out_dir.join(format!("{}.cand.png", tc.id));
    if let Err(e) = write_png(&ref_png, reference.framebuffer()) {
        eprintln!("warning: {}: {e}", ref_png.display());
