230	            Region::Iwram => write_le32(&mut self.iwram, (address as usize) & (IWRAM_SIZE - 1), value),
231	            Region::Io => self.io_write32(io_offset(address), value),
232	            Region::Palette => write_le32(&mut self.ppu.palette, (address & 0x3FF) as usize, value),
233	            Region::Vram => write_le32(&mut self.ppu.vram, vram_offset(address), value),
234	            Region::Oam => write_le32(&mut self.ppu.oam, (address & 0x3FF) as usize, value),
235	            Region::Sram => self.cart.sram_write8(address, value as u8),
