245	/// IO offset from 0x04000000. Only 0x000-0x3FF and 0x800-0x803 are registers; the rest reads 0.
246	fn io_offset(address: u32) -> u32 {
247	    let offset = address & 0x00FF_FFFF;
248	    if offset < 0x400 || (0x800..0x804).contains(&offset) {
249	        offset
250	    } else {
