#[derive(Clone, Copy, Default, Debug)]
pub struct LayerPixel {
    /// BGR555 colour.
    pub color: u16,
    /// 0 (front) to 3 (back).
    pub priority: u8,
    pub is_transparent: bool,
    pub is_semi_transparent_sprite: bool,
}

/// What happened during a `Ppu::step`, for gba.rs to forward to DMA.
#[derive(Clone, Copy, Default, Debug)]
