    fn refresh_vcount_flag(&mut self) -> bool {
        let matches = self.vcount == self.dispstat >> 8;
        if matches {
            self.dispstat |= DISPSTAT_VCOUNT_FLAG;
        } else {
            self.dispstat &= !DISPSTAT_VCOUNT_FLAG;
        }
        matches
    }

